#include "bootstrap_v2.h"
#include "manager_runtime_v2.h"
#include <cstdio>
#include <stdexcept>
#include <unistd.h>
using namespace recovery::v2;
namespace {
unsigned checks{};void check(bool ok,const char* what){++checks;if(!ok)throw std::runtime_error(what);}
runtime::Profile profile(){runtime::Profile p;p.selection=runtime::Selection::Synthetic;p.qualification="synthetic-inert-v2";p.managerVersion="249";p.powerRoutes="synthetic-no-sleep";p.timing=syntheticTiming();p.timing.grantLifetime=200;p.timing.drainLead=60;p.timing.stopGrace=20;p.timing.killGrace=20;p.timing.proofWindow=50;p.timing.sleepAllowance=100;for(auto n:{&p.timing.healthCadence,&p.timing.challengeLifetime,&p.timing.healthMaxAge,&p.timing.grantLifetime,&p.timing.drainLead,&p.timing.startupBudget,&p.timing.stopGrace,&p.timing.killGrace,&p.timing.proofWindow,&p.timing.sleepAllowance,&p.timing.clockSkew})*n*=1000000;for(auto& w:p.timing.workerPolicies)w.maxPendingAge*=1000000;p.fuse={35000000,35000000,5000000};p.readerCeiling=10000000000;p.ownerCeiling=20000000000;p.callBudget=1000000;p.startBudget=20000000;p.stopBudget=10000000;return p;}
SessionIdentity identity(){SessionIdentity i;text(i.session,"0123456789abcdef0123456789abcdef");text(i.boot,"01234567-89ab-cdef-0123-456789abcdef");text(i.invocation,"11111111111111111111111111111111");text(i.ownerInvocation,"22222222222222222222222222222222");text(i.mount,"/sys/fs/cgroup/unified");i.ownerPid=234;i.mainPid=235;i.device=21;i.inode=4097;i.ticket.fill(0x7b);setUnitNames(i);return i;}
}
int main(){try{
 auto p=profile();check(runtime::valid(p),"explicit synthetic profile valid");check(!runtime::valid({}),"absent profile is unsupported");auto id=identity();check(validIdentity(id),"valid synthetic identity");check(runtime::allowsStock(p,id.session.data(),"inkbound-stock-v2-test-"+std::string(id.session.data())+".service"),"exact synthetic stock");check(!runtime::allowsStock(p,id.session.data(),"xochitl.service"),"synthetic cannot select real stock");auto invalid=p;invalid.ownerCeiling=invalid.readerCeiling;check(!runtime::valid(invalid),"proof reserve required");invalid=p;invalid.fuse.leaseLifetime=0;check(!runtime::valid(invalid),"finite fuse required");
 auto wanted=runtime::requested(p,runtime::Role::Reader,id.owner.data(),"exact-fuse.service");check(wanted.bindsTo.size()==2&&wanted.bindsTo[0]==id.owner.data()&&wanted.bindsTo[1]=="exact-fuse.service","both dependencies represented");check(runtime::matches(wanted,wanted),"same actual profile");auto observed=wanted;observed.bindsTo.pop_back();check(!runtime::matches(wanted,observed),"fuse dependency required");observed=wanted;observed.killSignal=15;check(!runtime::matches(wanted,observed),"first signal SIGKILL required");observed=wanted;observed.notifyAccess="all";check(!runtime::matches(wanted,observed),"notify authority exact");observed=wanted;observed.runtimeUsec=~std::uint64_t(0);check(!runtime::matches(wanted,observed),"fixed reader ceiling required");
 bootstrap::Packet offer;offer.kind=bootstrap::Kind::Offer;offer.identity=id;offer.generation=7;offer.started={1000000000,9000000000,11};text(offer.profile,p.qualification);Wire wire;check(bootstrap::encode(offer,wire),"bootstrap encode");check(bootstrap::decode(wire)==offer,"bootstrap exact roundtrip");check(!decode(wire),"bootstrap cannot decode as protocol V2 grant");
 for(unsigned i=0;i<16;++i){auto bad=wire;bad[i]^=0x80;check(!bootstrap::decode(bad),"malformed bootstrap header");}auto bad=wire;bad.back()=1;check(!bootstrap::decode(bad),"nonzero padding rejected");check(!bootstrap::decode(std::span<const std::uint8_t>(wire.data(),wire.size()-1)),"truncated bootstrap rejected");
 VerifiedPeer peer{0,id.ownerPid,99,true};bootstrap::Child child;check(child.offer(offer,peer,id,p.qualification,offer.started,p.timing),"locally verified original offer");auto ack=child.acknowledgement();check(ack&&ack->kind==bootstrap::Kind::Acknowledged,"exact offer acknowledgement");check(!child.permitted(),"ack is not admission");auto permit=offer;permit.kind=bootstrap::Kind::Permit;check(child.permit(permit,peer,offer.started,p.timing),"one original permit");check(child.permitted(),"permitted startup");check(!child.permit(permit,peer,offer.started,p.timing)&&!child.permitted(),"replay seals bootstrap");
 bootstrap::Child replaced;check(replaced.offer(offer,peer,id,p.qualification,offer.started,p.timing),"second valid fixture");++peer.connection;check(!replaced.permit(permit,peer,offer.started,p.timing),"replacement socket cannot carry permit");--peer.connection;
 bootstrap::Child stale;check(stale.offer(offer,peer,id,p.qualification,offer.started,p.timing),"third valid fixture");auto late=offer.started;late.monotonic+=p.timing.startupBudget;late.boottime+=p.timing.startupBudget;check(!stale.permit(permit,peer,late,p.timing),"startup deadline immutable");
 OwnerMachine machine(id,7,p.timing,{0,id.mainPid,100,true},0,offer.started);machine.close(offer.started);check(machine.closure().has_value(),"owner closure exists");auto receipt=offer;receipt.kind=bootstrap::Kind::Receipt;receipt.closure=*machine.closure();receipt.witnessPid=345;receipt.drained=true;check(bootstrap::encode(receipt,wire)&&bootstrap::decode(wire)==receipt,"typed witness receipt roundtrip");receipt.drained=false;check(!bootstrap::encode(receipt,wire),"undrained witness cannot claim receipt");
 std::printf("RUNTIME_V2_BOUNDARY_PASS checks=%u manager=COMPILED_NOT_INVOKED profile=SYNTHETIC production_owner_dispatch=NOT_WIRED\n",checks);return 0;
 }catch(const std::exception& e){std::fprintf(stderr,"RUNTIME_V2_BOUNDARY_FAIL %s checks=%u\n",e.what(),checks);return 1;}}
